(()=>{
'use strict';
const root=document.getElementById('mivApp');if(!root)return;
const $=s=>root.querySelector(s), $$=s=>[...root.querySelectorAll(s)];
const K_SETTINGS='miv-standalone-settings-v1',K_QUOTES='miv-standalone-quotes-v1',K_DRAFT='miv-standalone-draft-v1';
const defaults={normalRate:90,batteryRate:120,namRate:70,paymentRate:3,adminRate:8,fxRate:2.50,quotePrefix:'MIV',validDays:3,disclaimer:'Shipping quotation is based on the product weight and information available at the time of quotation. Final shipping charges may vary if the supplier packaged weight, dimensions, cargo classification or other shipping information differs from the information supplied.'};
let settings={...defaults,...read(K_SETTINGS,{})},activeId=null,calc={},extracted=null,draftTimer=null,serverOrders=[],activeOrder=null,quoteOverrides=null;
const num=(v,max=1e9)=>{const n=Number(v);return Number.isFinite(n)?Math.min(max,Math.max(0,n)):0};
const qty=v=>Math.max(1,Math.floor(num(v,100000)||1));
const money=n=>'N$'+num(n).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const yuan=n=>'¥'+num(n).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
function read(k,f){try{return JSON.parse(localStorage.getItem(k))||f}catch{return f}}
function write(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{toast('Browser storage is full or unavailable. This quote has not been saved.');return false}}
const roundMoney=n=>Math.round((n+Number.EPSILON)*100)/100;
function quoteRates(){return quoteOverrides||settings}
function localDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function toast(t){const e=$('#mivToast');e.textContent=t;e.classList.add('is-show');clearTimeout(e._t);e._t=setTimeout(()=>e.classList.remove('is-show'),2200)}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function quotes(){return read(K_QUOTES,[])}
function nextRef(){const y=new Date().getFullYear(),p=(settings.quotePrefix||'MIV').toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,8)||'MIV';return `${p}-${y}-${crypto.randomUUID().slice(0,8).toUpperCase()}`}
function snapshot(){const r=quoteRates();return Object.fromEntries(['normalRate','batteryRate','namRate','paymentRate','adminRate','fxRate'].map(k=>[k,num(r[k])]))}
function showTab(name){$$('.miv-tabs button').forEach(b=>b.classList.toggle('is-active',b.dataset.tab===name));$$('.miv-view').forEach(v=>v.classList.toggle('is-active',v.dataset.view===name));if(name==='saved')renderSaved();if(name==='orders')loadOrders();document.body.classList.toggle('month-page',name==='budgets');if(name==='budgets'&&!budgetEditing)openMonth();if(name==='settings')loadSettings()}
function itemRow(d={}){const e=document.createElement('article');e.className='miv-item';e.innerHTML=`<div class="miv-item-head"><b>Order item</b><button class="miv-remove" type="button" aria-label="Remove item">×</button></div><div class="miv-item-grid"><label>Product<input class="i-name" placeholder="Product name"></label><label>Qty<input class="i-qty" type="number" min="1" step="1"></label><label>Weight (kg)<input class="i-weight" type="number" min="0" step="0.001" placeholder="0.000"></label><label>Cargo<select class="i-cargo"><option value="normal">Normal</option><option value="battery">Battery / Electronic</option></select></label></div><div class="miv-item-grid2"><label>Weight entered is<select class="i-weight-type"><option value="total">Total for quantity</option><option value="unit">Per unit</option></select></label><label>Weight source<select class="i-source"><option>Supplier/App Weight</option><option>Manually Entered</option><option>AI Estimated</option></select></label><label>Item price (¥ CNY)<input class="i-price" type="number" min="0" step="0.01" placeholder="0.00"></label><label>Price entered is<select class="i-price-type"><option value="unit">Per unit</option><option value="total">Total for quantity</option></select></label></div>`;$('#items').appendChild(e);e.querySelector('.i-name').value=d.name||'';e.querySelector('.i-qty').value=d.quantity||1;e.querySelector('.i-weight').value=d.weight??'';e.querySelector('.i-cargo').value=d.cargo||'normal';e.querySelector('.i-weight-type').value=d.weightType||'total';e.querySelector('.i-source').value=d.source||'Supplier/App Weight';e.querySelector('.i-price').value=d.price??'';e.querySelector('.i-price-type').value=d.priceType||'unit';e.querySelector('.miv-remove').onclick=()=>{e.remove();if(!$$('.miv-item').length)itemRow();update()};e.querySelectorAll('input,select').forEach(x=>{x.addEventListener('input',update);x.addEventListener('change',update)});update()}
function items(){return $$('.miv-item').map(r=>{const q=qty(r.querySelector('.i-qty').value),w=num(r.querySelector('.i-weight').value),wt=r.querySelector('.i-weight-type').value,p=num(r.querySelector('.i-price').value),pt=r.querySelector('.i-price-type').value;return{name:r.querySelector('.i-name').value.trim()||'Item',quantity:q,weight:w,weightType:wt,totalWeight:wt==='unit'?w*q:w,cargo:r.querySelector('.i-cargo').value,source:r.querySelector('.i-source').value,price:p,priceType:pt,totalItemCny:pt==='unit'?p*q:p}})}
function deliveryOnly(q){return (q?q.quoteType:$('#quoteType').value)==='delivery_only'}
function orderDelivery(o){return o.quote_type==='delivery_only'}
function calculate(rates=quoteRates()){let totalWeight=0,itemsCny=0,china=0;const rows=items();rows.forEach(i=>{totalWeight+=i.totalWeight;itemsCny+=i.totalItemCny;china+=i.totalWeight*(i.cargo==='battery'?num(rates.batteryRate):num(rates.normalRate))});const payment=china*num(rates.paymentRate)/100,chinaNad=(china+payment)*num(rates.fxRate),nam=totalWeight*num(rates.namRate),adminBase=chinaNad+nam,admin=adminBase*num(rates.adminRate)/100,shipping=roundMoney(adminBase+admin),itemsNad=deliveryOnly()?0:roundMoney(itemsCny*num(rates.fxRate)),total=roundMoney(itemsNad+shipping);return{items:rows,totalWeight,itemsCny,itemsNad,china,payment,chinaNad,nam,admin,shipping,total}}
function update(){calc=calculate();const only=deliveryOnly();$$('.i-price,.i-price-type').forEach(e=>{e.disabled=only;e.closest('label').hidden=only});$('#outItemsCny').closest('div').hidden=only;$('#outItemsNad').closest('div').hidden=only;$('#outWeight').textContent=calc.totalWeight.toFixed(3)+' kg';$('#outItemsCny').textContent=yuan(calc.itemsCny);$('#outItemsNad').textContent=money(calc.itemsNad);$('#outChina').textContent=yuan(calc.china);$('#outPayment').textContent=yuan(calc.payment);$('#outChinaNad').textContent=money(calc.chinaNad);$('#outNam').textContent=money(calc.nam);$('#outAdmin').textContent=money(calc.admin);$('#outShipping').textContent=money(calc.shipping);$('#outTotal').textContent=money(calc.total);$('#outBasis').textContent=`${deliveryOnly()?'Delivery only':'Items + shipping'} · ${calc.totalWeight.toFixed(3)} kg`;$('#liveWeight').textContent=calc.totalWeight.toFixed(3)+' kg';$('#liveTotal').textContent=money(calc.total);scheduleDraft()}
function valid(){if(!$('#customer').value.trim()){toast('Enter the customer name.');return false}const a=items();if($$('.i-name').some(e=>!e.value.trim())){toast('Enter a description for every item.');return false}if(a.some(i=>i.totalWeight<=0)){toast('Every item needs a confirmed weight.');return false}if(!deliveryOnly()&&a.some(i=>i.totalItemCny<=0)){toast('Every item needs a price.');return false}if(num(quoteRates().fxRate)<=0){toast('Set the CNY to NAD exchange rate.');return false}return true}
function draft(){return{activeId,quoteOverrides,quoteType:$('#quoteType').value,customer:$('#customer').value,phone:$('#phone').value,reference:$('#reference').value,status:$('#status').value,items:items()}}
function scheduleDraft(){clearTimeout(draftTimer);draftTimer=setTimeout(()=>{const d=draft();if(d.customer||d.reference||d.items.some(i=>i.weight||i.price||i.name!=='Item')){if(write(K_DRAFT,d))$('#draftStatus').textContent='Draft saved automatically · '+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}},180)}
function restoreDraft(){const d=read(K_DRAFT,null);if(!d)return false;activeId=d.activeId||null;quoteOverrides=d.quoteOverrides||null;$('#quoteType').value=d.quoteType||'goods_delivery';$('#customer').value=d.customer||'';$('#phone').value=d.phone||'';$('#reference').value=d.reference||'';$('#status').value=d.status||'Draft';$('#items').innerHTML='';(d.items||[]).forEach(itemRow);if(!d.items?.length)itemRow();$('#draftStatus').textContent='Recovered your auto-saved draft.';return true}
function reset(){$('#quoteType').value='goods_delivery';activeId=null;quoteOverrides=null;clearTimeout(draftTimer);localStorage.removeItem(K_DRAFT);$('#customer').value='';$('#phone').value='';$('#reference').value='';$('#status').value='Draft';$('#items').innerHTML='';itemRow();clearImage();$('#draftStatus').textContent='Draft saves automatically on this device.';update()}
function quoteObject(){calc=calculate();if(!$('#reference').value.trim())$('#reference').value=nextRef();return{id:activeId||('q_'+Date.now()+'_'+Math.random().toString(36).slice(2,6)),quoteType:$('#quoteType').value,customer:$('#customer').value.trim(),phone:$('#phone').value.trim(),reference:$('#reference').value.trim()||nextRef(),status:$('#status').value,createdAt:quotes().find(q=>q.id===activeId)?.createdAt||new Date().toISOString(),items:calc.items,totalWeight:calc.totalWeight,itemsNad:calc.itemsNad,shippingTotal:calc.shipping,total:calc.total,rateSnapshot:snapshot(),disclaimer:quoteRates().disclaimer,validDays:quoteRates().validDays}}
function saveQuote(){if(!valid())return null;const q=quoteObject();activeId=q.id;$('#reference').value=q.reference;const a=quotes(),i=a.findIndex(x=>x.id===q.id);if(i>=0){q.createdAt=a[i].createdAt;q.updatedAt=new Date().toISOString();a[i]=q}else a.unshift(q);if(!write(K_QUOTES,a))return null;write(K_DRAFT,draft());toast('Quote saved.');renderSaved();return q}
