}
async function saveOrderState(){
  if(!activeOrder)return;
  try{
    const data=await api({action:'update_order',order_id:Number(activeOrder.id),payment_plan:$('#oPlan').value,order_stage:$('#oStage').value});
    activeOrder=data.order;
    await loadOrders();
    await openOrder(activeOrder);
    toast('Order stage updated.');
  }catch(e){toast(e.message||'Could not update order.')}
}
async function recordPayment(){
  if(!activeOrder)return;
  const amount=num($('#payAmount').value);
  if(amount<=0){toast('Enter a payment amount.');return}
  const payload={action:'record_payment',order_id:Number(activeOrder.id),component:$('#payComponent').value,amount,payment_method:$('#payMethod').value,paid_at:$('#payDate').value,note:$('#payNote').value.trim()};
  const signature=JSON.stringify(payload);
  try{
    $('#recordPayment').disabled=true;
    let pending=JSON.parse(sessionStorage.getItem('miv-pending-payment')||'null');
    if(!pending||pending.signature!==signature){pending={signature,id:crypto.randomUUID()};sessionStorage.setItem('miv-pending-payment',JSON.stringify(pending))}
    const data=await api({...payload,request_id:pending.id});
    sessionStorage.removeItem('miv-pending-payment');
    activeOrder=data.order;
    await loadOrders();
    await openOrder(activeOrder);
    toast('Payment recorded.');
  }catch(e){toast(e.message||'Could not record payment.')}
  finally{$('#recordPayment').disabled=false}
}

